def text_lowercase_underscore(text):
    if '_' in text:
        parts = text.split('_')
        for part in parts:
            if not all(c.islower() and c.isalpha() for c in part) or len(part) == 0:
                return False
        return True
    else:
        return any(c.islower() and c.isalpha() for c in text)
